"""Independent naive reference implementation of PROTOCOL.md (slow, exact)."""
import itertools
import operator

OPS = {'eq': operator.eq, 'ne': operator.ne, 'lt': operator.lt, 'le': operator.le,
       'gt': operator.gt, 'ge': operator.ge}


def brute_job(job):
    fields = job['fields']
    F = len(fields)
    K = int(job['slots'])
    C = K * F
    names = {f['name']: i for i, f in enumerate(fields)}
    doms = [list(f['domain']) for f in fields]
    cell_dom = [doms[c % F] for c in range(C)]

    def ref_index(ref):
        return int(ref[0]) * F + names[ref[1]]

    def term_val(t, w):
        if 'const' in t:
            return int(t['const'])
        if 'sum' in t:
            return sum(w[ref_index(r)] for r in t['sum'])
        if 'scale' in t:
            return int(t['scale']) * w[ref_index(t['ref'])]
        return w[ref_index(t['ref'])]

    def pred_val(p, w):
        op = OPS[p['op']]
        if p['kind'] == 'cmp':
            return bool(op(term_val(p['left'], w), term_val(p['right'], w)))
        cells = [w[ref_index([s, p['field']])] for s in range(K)]
        if p['kind'] == 'any':
            return any(bool(op(v, p['value'])) for v in cells)
        return all(bool(op(v, p['value'])) for v in cells)

    universe = list(itertools.product(*cell_dom))
    U = len(universe)
    position = {w: i for i, w in enumerate(universe)}
    P = len(job['predicates'])
    # truth[p][u]
    truth = [[pred_val(p, w) for w in universe] for p in job['predicates']]

    train_flat = [tuple(v for row in window for v in row) for window in job['train']]
    train_idx = [position[w] for w in train_flat]
    N = len(train_idx)

    width = int(job['width'])
    rules = []
    for size in range(1, min(width, P) + 1):
        for clause in itertools.combinations(range(P), size):
            # condition 1
            if not all(any(truth[p][u] for p in clause) for u in train_idx):
                continue
            # condition 2 + witnesses
            witnesses = []
            ok = True
            for p in clause:
                others = [q for q in clause if q != p]
                hits = [i for i, u in enumerate(train_idx)
                        if truth[p][u] and not any(truth[q][u] for q in others)]
                if not hits:
                    ok = False
                    break
                witnesses.append(min(hits))
            if not ok:
                continue
            # condition 3
            falsifiers = [u for u in range(U) if not any(truth[p][u] for p in clause)]
            if not falsifiers:
                continue
            rules.append({'clause': list(clause), 'witnesses': witnesses,
                          'counterexample': min(falsifiers)})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))

    approved = {tuple(sorted(c)) for c in job['approved'] if c}
    active = [r['clause'] for r in rules if tuple(r['clause']) in approved]

    def theory_ok(u):
        return all(any(truth[p][u] for p in clause) for clause in active)

    answers = []
    for q in job['queries']:
        target_cell = ref_index(q['target'])
        prefix = str(q['prefix'])
        fixed = [(ref_index(b['ref']), int(b['value'])) for b in q['fixed']]
        allowed = [u for u in range(U) if theory_ok(u)
                   and all(universe[u][c] == v for c, v in fixed)]
        spell = {u: str(universe[u][target_cell]) for u in allowed}
        completions = [u for u in allowed if spell[u].startswith(prefix)]
        tokens = []
        for d in '0123456789':
            if any(spell[u].startswith(prefix + d) for u in allowed):
                tokens.append(d)
        if prefix and any(spell[u] == prefix for u in allowed):
            tokens.append('END')
        answers.append({'count': len(completions), 'tokens': tokens,
                        'witness': min(completions) if completions else None})
    return {'rules': rules, 'active': active, 'answers': answers}


def brute_batch(batch):
    return {'results': [brute_job(job) for job in batch['jobs']]}
