"""Random protocol job/batch generator for differential fuzzing."""
import random


def gen_domain(rng, max_size=4, max_value=40):
    size = rng.randint(1, max_size)
    values = rng.sample(range(0, max_value), size)
    return sorted(values)


def gen_job(rng, width=None):
    F = rng.randint(1, 3)
    K = rng.randint(1, 3)
    if rng.random() < 0.15:
        K = 1
    types = ['time', 'size', 'count', 'id', 'flag']
    fields = []
    for i in range(F):
        t = rng.choice(types)
        if t in ('id', 'flag'):
            dom = gen_domain(rng, max_size=3, max_value=20)
        else:
            dom = gen_domain(rng, max_size=4, max_value=60)
        fields.append({'name': f'f{i}', 'type': t, 'domain': dom})
    names = [f['name'] for f in fields]
    numeric = [n for n, f in zip(names, fields) if f['type'] in ('time', 'size', 'count')]
    same_type = {}
    for f in fields:
        same_type.setdefault(f['type'], []).append(f['name'])

    preds = []
    P = rng.randint(1, 7)
    for _ in range(P):
        kind = rng.choice(['cmp', 'cmp', 'cmp', 'any', 'all'])
        if kind == 'cmp':
            op = rng.choice(['eq', 'ne', 'lt', 'le', 'gt', 'ge'])

            def term(t=None):
                choices = ['ref', 'const', 'sum', 'scale']
                if t in ('id', 'flag'):
                    choices = ['ref', 'const']
                if not numeric:
                    choices = ['ref', 'const']
                pick = rng.choice(choices)
                if pick == 'ref':
                    return {'ref': [rng.randrange(K), rng.choice(names)]}
                if pick == 'const':
                    return {'const': rng.choice([0, 1, 2, 5, 10, 20, 30, 60, 100]), 'type': t or 'count'}
                if pick == 'sum':
                    fam = rng.choice(numeric)
                    ftype = next(f['type'] for f in fields if f['name'] == fam)
                    refs = rng.sample([[s, fam] for s in range(K)], rng.randint(1, K))
                    return {'sum': refs}
                return {'scale': rng.choice([0, 1, 2, 3, 7]),
                        'ref': [rng.randrange(K), rng.choice(numeric)]}
            # choose a type-consistent pair
            if rng.random() < 0.5:
                f = rng.choice(fields)
                left = {'ref': [rng.randrange(K), f['name']]}
                if f['type'] in ('id', 'flag'):
                    op = rng.choice(['eq', 'ne'])
                    right = {'const': rng.choice(f['domain'] + [0, 1, 2, 3, 7, 99]), 'type': f['type']}
                else:
                    right = term(f['type'])
                    if 'sum' in right or 'scale' in right:
                        pass
                preds.append({'kind': 'cmp', 'left': left, 'op': op, 'right': right})
            else:
                if numeric:
                    fam = rng.choice(numeric)
                    ftype = next(f['type'] for f in fields if f['name'] == fam)
                    left = term(ftype)
                    if 'ref' in left:
                        # ensure same type: rebuild restricted to family
                        left = {'ref': [rng.randrange(K), fam]}
                    right = {'const': rng.choice([0, 1, 2, 3, 5, 10, 20, 30, 60, 120]), 'type': ftype}
                    if 'sum' in left or 'scale' in left:
                        pass
                else:
                    f = rng.choice(fields)
                    left = {'ref': [rng.randrange(K), f['name']]}
                    right = {'const': rng.choice(f['domain'] + [0, 1, 99]), 'type': f['type']}
                    op = rng.choice(['eq', 'ne'])
                preds.append({'kind': 'cmp', 'left': left, 'op': op, 'right': right})
        else:
            f = rng.choice(fields)
            op = rng.choice(['eq', 'ne'] if f['type'] in ('id', 'flag') else ['eq', 'ne', 'lt', 'le', 'gt', 'ge'])
            value = rng.choice(f['domain'] + [0, 1, 2, 3, 7, 15, 30, 60, 100])
            preds.append({'kind': kind, 'field': f['name'], 'op': op, 'value': value})

    if width is None:
        width = rng.randint(1, 4)
    # training windows
    U = 1
    for _ in range(K):
        for f in fields:
            U *= len(f['domain'])
    n_train = rng.randint(1, min(20, max(1, U)))
    train = []
    for _ in range(n_train):
        train.append([[rng.choice(f['domain']) for f in fields] for _ in range(K)])
    if rng.random() < 0.3 and train:
        train.append([row[:] for row in train[0]])  # duplicate record

    approved = []
    seen = set()
    for _ in range(rng.randint(0, 6)):
        size = rng.randint(1, min(width, len(preds)))
        clause = tuple(sorted(rng.sample(range(len(preds)), size)))
        if clause in seen:
            continue
        seen.add(clause)
        approved.append(list(clause))

    queries = []
    for _ in range(rng.randint(1, 6)):
        tslot = rng.randrange(K)
        tname = rng.choice(names)
        others = [(s, n) for s in range(K) for n in names if (s, n) != (tslot, tname)]
        fixed = []
        if others and rng.random() < 0.7:
            for s, n in rng.sample(others, rng.randint(1, min(3, len(others)))):
                f = next(ff for ff in fields if ff['name'] == n)
                fixed.append({'ref': [s, n], 'value': rng.choice(f['domain'])})
        style = rng.random()
        if style < 0.25:
            prefix = ''
        elif style < 0.5:
            f = next(ff for ff in fields if ff['name'] == tname)
            prefix = str(rng.choice(f['domain']))
        elif style < 0.7:
            prefix = rng.choice(['0', '00', '01', '1', '10', '2', '9', '007', '1000000', '99'])
        else:
            prefix = ''.join(rng.choice('0123456789') for _ in range(rng.randint(1, 7)))
        queries.append({'target': [tslot, tname], 'prefix': prefix, 'fixed': fixed})

    return {'fields': fields, 'slots': K, 'predicates': preds, 'width': width,
            'train': train, 'approved': approved, 'queries': queries}


def gen_batch(rng, jobs=None):
    if jobs is None:
        jobs = rng.randint(1, 3)
    return {'jobs': [gen_job(rng) for _ in range(jobs)]}
